/* ───── Helpers de consulta ───── */

/** Participantes de una disciplina y categoría. Puede devolver []. */
export function getParticipantes(disciplinaId, categoria) {
  return PARTICIPANTES_SICE.filter(
    p => p.disciplinaId === disciplinaId && (!categoria || p.categoria === categoria)
  );
}

/** IIEE que tienen al menos un inscrito en esa disciplina y categoría. */
export function getIIEEConInscritos(disciplinaId, categoria) {
  const ids = new Set(getParticipantes(disciplinaId, categoria).map(p => p.iieeId));
  return IIEE_UGEL03.filter(ie => ids.has(ie.id));
}

/** Búsqueda tolerante: ignora tildes, mayúsculas y espacios extra. */
export function normalizar(texto) {
  return String(texto || "")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .toLowerCase().replace(/\s+/g, " ").trim();
}

/** Busca por I. E., título, seudónimo o código. Devuelve como máximo `limite`. */
export function buscarParticipantes(texto, { disciplinaId, categoria, limite = 20 } = {}) {
  const t = normalizar(texto);
  let base = PARTICIPANTES_SICE;
  if (disciplinaId) base = base.filter(p => p.disciplinaId === disciplinaId);
  if (categoria) base = base.filter(p => p.categoria === categoria);
  if (!t) return base.slice(0, limite);
  return base
    .filter(p =>
      normalizar(p.iiee).includes(t) ||
      normalizar(p.titulo).includes(t) ||
      normalizar(p.seudonimo).includes(t) ||
      normalizar(p.codigo).includes(t)
    )
    .slice(0, limite);
}

/** Conteo de inscritos por disciplina y categoría. */
export function contarInscritos(disciplinaId, categoria) {
  return getParticipantes(disciplinaId, categoria).length;
}

/** Combinaciones disciplina + categoría que efectivamente tienen inscritos. */
export function getCombinacionesConInscritos() {
  const m = new Map();
  PARTICIPANTES_SICE.forEach(p => {
    const k = p.disciplinaId + "|" + p.categoria;
    if (!m.has(k)) m.set(k, { disciplinaId: p.disciplinaId, disciplina: p.disciplina, categoria: p.categoria, total: 0 });
    m.get(k).total++;
  });
  return Array.from(m.values());
}
